<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {request} from '../api'
import {newId} from '../ids'
import {confirmAction} from '../ui/confirm'
import ValueInput from '../admin/ValueInput.vue'
import RecordMapping from './RecordMapping.vue'
import ResourceMapping from './ResourceMapping.vue'
import ArticleBody from '../reading/ArticleBody.vue'
import type {Field,TypeSummary} from '../admin/types'
import {clone,kinds} from '../admin/types'
const props=defineProps<{initialJobId?:string}>()
const emit=defineEmits<{(e:'completed',recordIds:string[]):void}>()
const types=ref<TypeSummary[]>([]),selectedType=ref(''),file=ref<File|null>(null),requestKey=ref(''),job=ref<any>(null),draft=ref<any>(null)
const busy=ref(false),error=ref(''),notice=ref(''),dirty=ref(false),accepted=ref(false),newFilePending=ref(false)
const editable=computed(()=>job.value&&['preview','failed'].includes(job.value.state))
const canConfirm=computed(()=>editable.value&&!newFilePending.value&&job.value.valid&&!job.value.stale_context&&!dirty.value&&accepted.value&&!busy.value)
function adopt(value:any,fromUpload=false){if(value.state==='completed')emit('completed',value.result_ids||[]);if(fromUpload)newFilePending.value=false;job.value=value;draft.value=clone(value.input);dirty.value=false;accepted.value=false;if(value.id)sessionStorage.setItem('lj-exchange-job',value.id)}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e);const detail=(e as any)?.detail;if(detail?.errors)error.value+='：'+detail.errors.map((item:any)=>item.loc.join('.')+' '+item.msg).join('；')}finally{busy.value=false}}
function choose(event:Event){if(busy.value)return;accepted.value=false;error.value='';notice.value='';const selected=(event.target as HTMLInputElement).files?.[0]||null;file.value=null;requestKey.value='';newFilePending.value=!!selected;if(!selected)return;try{requestKey.value=newId();file.value=selected}catch(e){error.value=e instanceof Error?e.message:String(e)}}
async function upload(){if(!file.value)return;const body=new FormData();body.append('file',file.value);await run(async()=>{adopt(await request('/admin/exchange/preview',{method:'POST',headers:{'X-Import-Key':requestKey.value},body}),true);notice.value='预览已保存，尚未创建文章或媒体库资源。'})}
async function reload(){if(!job.value||dirty.value&&!await confirmAction('映射有未校验修改，放弃并重新读取服务器预览？'))return;await run(async()=>adopt(await request('/admin/exchange/jobs/'+job.value.id)))}
async function remap(){await run(async()=>{adopt(await request('/admin/exchange/jobs/'+job.value.id+'/mapping',{method:'PUT',body:JSON.stringify({expected_revision:job.value.revision,content:draft.value})}));notice.value='映射已重新校验，请检查正文、日期和照片后确认。'})}
async function confirm(){if(!canConfirm.value||!await confirmAction('按当前预览创建新草稿和媒体关联？不会发布，也不会覆盖已有文章。'))return;await run(async()=>{adopt(await request('/admin/exchange/jobs/'+job.value.id+'/confirm',{method:'POST',body:JSON.stringify({expected_revision:job.value.revision,confirmation:'创建草稿'})}));notice.value='草稿已创建。请进入编辑页审核，再按原有流程发布。'})}
async function cancel(){if(!await confirmAction('取消此次导入？不会删除原有文章和媒体库资源。'))return;await run(async()=>{await request('/admin/exchange/jobs/'+job.value.id+'/cancel',{method:'POST',body:JSON.stringify({expected_revision:job.value.revision})});await reloadDirect();notice.value='已取消，原有内容和媒体未修改。'})}
async function reloadDirect(){adopt(await request('/admin/exchange/jobs/'+job.value.id))}
function change(){dirty.value=true;accepted.value=false}
function typeChanged(record:any){record.schema_version=null;record.template_slug=null;record.template_version=null;change();notice.value='切换类型后请先重新校验，再按新类型映射字段。'}
function recordContext(record:any){const table=job.value?.contexts;return table&&Object.hasOwn(table,record.key)?table[record.key]:undefined}
function fieldsFor(record:any):Field[]{return recordContext(record)?.type.fields||[]}
function fieldTarget(record:any,key:string){return fieldsFor(record).some(f=>f.id===key)?key:(job.value.records.find((r:any)=>r.key===record.key)?.field_mapping||[]).find((m:any)=>m.source===key)?.field_id||''}
async function mapField(record:any,key:string,event:Event){const target=(event.target as HTMLSelectElement).value;if(!target||target===key)return;if(target==='__skip'){if(!await confirmAction('仅不导入此来源字段？不会修改原文件或现有文章。'))return;delete record.values[key]}else{if(target in record.values&&JSON.stringify(record.values[target])!==JSON.stringify(record.values[key])){error.value='目标字段已有不同值，未覆盖；请先核对来源字段。';return}record.values[target]=record.values[key];delete record.values[key]}change()}
async function currentVersion(record:any){const ctx=recordContext(record);if(!ctx||ctx.type.slug!==record.type_slug||!await confirmAction('按当前字段和模板版本重新映射此新草稿？原文件及已有文章不会修改，请逐项核对保留的字段值。'))return;record.schema_version=ctx.type.version;record.template_version=ctx.template?.version||null;record.template_slug=ctx.template?.slug||null;change()}
function fieldValue(record:any,field:Field){const id=field.id;if(!id)return null;return Object.hasOwn(record.values,id)?record.values[id]:job.value.records.find((r:any)=>r.key===record.key)?.values?.[id]??null}
function setField(record:any,field:Field,value:unknown){const mapped=job.value.records.find((r:any)=>r.key===record.key)?.field_mapping||[];for(const m of mapped)if(m.field_id===field.id)delete record.values[m.source];record.values[field.id!]=value;change()}
async function exportSpec(){if(!selectedType.value)return;await run(async()=>{const blob=await request('/admin/exchange/specification',{method:'POST',body:JSON.stringify({type_slug:selectedType.value})}) as Blob;const url=URL.createObjectURL(blob);try{const link=document.createElement('a');link.href=url;link.download='life-journal-writing-spec.zip';link.click()}finally{setTimeout(()=>URL.revokeObjectURL(url),1000)}})}
onMounted(()=>void run(async()=>{types.value=await request('/admin/content/types');selectedType.value=types.value.find(t=>t.active)?.slug||'';const id=props.initialJobId||sessionStorage.getItem('lj-exchange-job');if(id&&/^[0-9a-f-]{36}$/.test(id))adopt(await request('/admin/exchange/jobs/'+id))}))
</script>
<template><main class="container exchange-admin"><header><p class="eyebrow">CONTENT EXCHANGE</p><h1>图文导入与写作规范</h1><p>使用同一份字段规范准备 Markdown、JSON 或包含真实照片的 ZIP。所有确认操作只创建新草稿，不覆盖历史文章。</p></header>
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="busy" role="status">正在处理，请勿重复提交…</p>
<section class="card"><h2>导出给 ChatGPT 的写作规范</h2><p>只包含类型、模板和格式规则；不导出文章、私人照片或模型密钥。</p><div class="actions"><label>内容类型<select v-model="selectedType" :disabled="busy"><option v-for="t in types.filter(t=>t.active)" :key="t.id" :value="t.slug">{{t.name}}</option></select></label><button :disabled="busy||!selectedType" @click="exportSpec">下载写作规范</button></div></section>
<section class="card"><h2>上传并检查</h2><p>ZIP 最大 50 MB；Markdown / JSON 最大 2 MB。照片仅支持经过内容验证的 JPEG、PNG、WebP。原图保留，预览去除 EXIF/GPS。</p><label>选择图文包<input type="file" accept=".zip,.md,.markdown,.json" :disabled="busy" @change="choose"></label><button :disabled="busy||!file" @click="upload">{{job?'预览新文件 / 重试上传':'生成导入预览'}}</button></section>
<section v-if="job" class="card"><div class="actions"><h2>预览 · {{job.state==='completed'?'已创建草稿':job.state==='cancelled'?'已取消':'待确认'}}</h2><button class="quiet" :disabled="busy" @click="reload">重新读取任务</button></div><p>任务修订 {{job.revision}}。临时预览保留 24 小时；取消不删除原有资源。</p><ul v-if="job.issues.length" class="exchange-issues"><li v-for="(issue,index) in job.issues" :key="index" :class="{error:issue.level==='error'}">{{issue.level==='error'?'需修正':'待补充'}} · {{issue.scope}}：{{issue.message}}</li></ul>
<form v-if="editable" @submit.prevent="remap" @input="change"><article v-for="record in draft.records" :key="record.key" class="exchange-record"><h3>{{record.title||'待命名文章'}}</h3><div class="exchange-fields"><label>目标内容类型<select v-model="record.type_slug" :disabled="busy" @change="typeChanged(record)"><option value="">请选择</option><option v-for="t in types.filter(t=>t.active)" :key="t.id" :value="t.slug">{{t.name}}</option></select></label><label>标题<input v-model="record.title" maxlength="200" :disabled="busy"></label><label>文章展示日期<input v-model="record.display_date" type="date" :disabled="busy"></label></div>
<p class="muted">文章展示日期与旅行、用餐日期分别保存，不会互相猜测。</p><button type="button" class="quiet" :disabled="busy||!recordContext(record)||recordContext(record).type.slug!==record.type_slug" @click="currentVersion(record)">重新绑定当前字段与模板版本</button><label>摘要（可留空）<textarea v-model="record.summary" maxlength="500" :disabled="busy" rows="2"/></label><label>原始正文<textarea v-model="record.body" :disabled="busy" rows="10" maxlength="300000"/></label>
<details v-if="Object.keys(record.values).length"><summary>来源字段映射（未匹配字段可在这里修正）</summary><label v-for="(value,key) in record.values" :key="String(key)">来源：{{key}} · {{JSON.stringify(value).slice(0,160)}}<select :value="fieldTarget(record,String(key))" :disabled="busy||recordContext(record)?.type.slug!==record.type_slug" @change="mapField(record,String(key),$event)"><option value="">请选择目标字段</option><option v-for="field in fieldsFor(record).filter(f=>f.active)" :key="field.id" :value="field.id">{{field.name}} · {{kinds[field.kind]}} · {{field.description||'字段'+(field.position+1)}}</option><option value="__skip">明确不导入此来源字段</option></select></label></details><template v-for="field in recordContext(record)?.type.fields||[]" :key="field.id"><ValueInput v-if="field.active" :field="field" :label="field.name+(field.required?'（发布前必填）':'')" :model-value="fieldValue(record,field)" :disabled="busy" @update:model-value="setField(record,field,$event)"/></template>
<ul v-if="job.records.find((r:any)=>r.key===record.key)?.parsed_places?.length"><li v-for="(place,index) in job.records.find((r:any)=>r.key===record.key).parsed_places" :key="index">正文标记：@{{place.kind}} {{place.name}} · {{place.city||'待分类'}} · {{place.action==='reuse'?'复用已有地点':'确认时新建'}}</li></ul><section v-if="!dirty&&!newFilePending&&job.valid&&job.records.find((r:any)=>r.key===record.key)?.compiled_body" class="exchange-body-preview"><h4>实际图文预览（尚未创建文章）</h4><ArticleBody :source="job.records.find((r:any)=>r.key===record.key).compiled_body" :format="2" :namespace="'exchange-'+job.id+'-'+record.key" :preview-media="job.images"/></section><RecordMapping :record="record" :content="draft" :disabled="busy" @change="change"/><details><summary>服务端生成的正式 Markdown（只读）</summary><pre>{{job.records.find((r:any)=>r.key===record.key)?.compiled_body||'修正映射并重新校验后显示'}}</pre></details></article><ResourceMapping :content="draft" :source-media="job.source_media" :planned-places="job.planned_places" :disabled="busy" @change="change"/><p v-if="newFilePending" role="status">新文件尚未上传校验，当前仍是上次预览，不能确认导入。</p><p v-if="dirty" role="status">映射有未校验的修改，不能直接确认导入。</p><button class="quiet" :disabled="busy" type="submit">重新校验映射与预览</button></form>
<div v-if="job.images.length" class="exchange-photos"><figure v-for="image in job.images" :key="image.id"><img :src="image.url" :width="image.width" :height="image.height" :alt="'导入照片 '+image.key" loading="lazy"><figcaption>{{image.key}}</figcaption></figure></div>
<div v-if="editable" class="exchange-confirm"><label><input v-model="accepted" type="checkbox" :disabled="busy||dirty||!job.valid">我已检查日期、字段、正文和图片，仅创建新草稿</label><div class="actions"><button :disabled="!canConfirm" @click="confirm">确认创建草稿</button><button class="quiet" :disabled="busy" @click="cancel">取消此导入</button></div></div>
<ul v-if="job.state==='completed'"><li v-for="id in job.result_ids" :key="id"><RouterLink :to="'/write/'+id">继续编辑草稿</RouterLink></li></ul></section></main></template>
<style scoped>
.exchange-admin{max-width:1160px}.exchange-admin>header{display:block}.exchange-admin>header h1{max-width:none}.exchange-admin>.card{margin-block:20px;padding:clamp(16px,3vw,28px)}.exchange-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:16px}.exchange-record{border-block-start:1px solid var(--ui-line);padding-block:16px}.exchange-admin textarea{width:100%;box-sizing:border-box;resize:vertical}.exchange-admin label{display:block}.exchange-photos{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,180px),1fr));gap:12px;margin-block:20px}.exchange-photos figure{margin:0;min-width:0}.exchange-photos img{width:100%;height:150px;object-fit:contain;background:var(--ui-card)}.exchange-admin pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:420px;overflow:auto;padding:16px;background:var(--ui-bg)}.exchange-confirm{border-block-start:1px solid var(--ui-line);padding-top:20px}.exchange-admin input[type=checkbox]{width:auto}.exchange-issues{padding-inline-start:22px;overflow-wrap:anywhere}@media(max-width:500px){.exchange-admin .actions{align-items:stretch}.exchange-admin .actions>label{width:100%}}
</style>
